{
  "name": "blackbird-opencode",
  "version": "0.4.0",
  "description": "Deliver durable Blackbird messages into OpenCode V2 sessions.",
  "type": "module",
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "import": "./dist/index.js"
    },
    "./server": "./dist/index.js",
    "./rpc": "./dist/rpc.js",
    "./tui": "./dist/tui.js"
  },
  "files": [
    "dist",
    "server.ts",
    "tui.tsx",
    "rpc.ts",
    "README.md",
    "LICENSE"
  ],
  "sideEffects": false,
  "engines": {
    "node": ">=22.0.0"
  },
  "scripts": {
    "compile": "bun scripts/build.mjs",
    "check": "tsc --noEmit && eslint src test",
    "test": "vitest run",
    "test:tui": "npm run compile && opencode-drive run scripts/tui-drive.ts",
    "test:pack": "npm run compile && node scripts/pack-test.mjs",
    "gates": "npm run check && npm test && npm run test:pack && npm audit --audit-level=high"
  },
  "keywords": [
    "blackbird",
    "opencode",
    "plugin",
    "agent"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/phall1/blackbird.git",
    "directory": "packages/opencode-plugin"
  },
  "bugs": {
    "url": "https://github.com/phall1/blackbird/issues"
  },
  "homepage": "https://github.com/phall1/blackbird/tree/main/packages/opencode-plugin#readme",
  "dependencies": {
    "@opencode/plugin": "2.0.32",
    "@opencode/schema": "2.0.32",
    "zod": "4.6.7"
  },
  "peerDependencies": {
    "effect": "^4.0.1",
    "@opentui/core": "0.5.17",
    "@opentui/solid": "0.5.17",
    "solid-js": "1.9.12"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.19.3",
    "@opencode/theme": "2.0.32",
    "effect": "4.0.1",
    "opencode-drive": "2.3.0",
    "@eslint/js": "10.0.1",
    "@types/node": "24.19.2",
    "eslint": "10.13.0",
    "typescript": "5.9.3",
    "typescript-eslint": "8.71.2",
    "vitest": "5.0.5"
  },
  "overrides": {
    "seroval": "1.6.9",
    "seroval-plugins": "1.6.9"
  },
  "publishConfig": {
    "access": "public",
    "provenance": true
  }
}
